// Protections are chosen from these bits, or-ed together
const (
	PROT_NONE = 0
	// [MC2] pages can be read
	PROT_READ = 1
	// [MC2] pages can be written
	PROT_WRITE = 2
	// [MC2] pages can be executed
	PROT_EXEC = 4
)

// Flags contain sharing type and options.
// Sharing types; choose one.
const (
	MAP_SHARED = 1
	// [MF|SHM] changes are private
	MAP_PRIVATE = 2
)

// Obsolete
const MAP_COPY = 2

// Other flags
const MAP_FIXED = 16

const (
	// Sun: rename private pages to file
	MAP_RENAME = 32
	// Sun: don't reserve needed swap area
	MAP_NORESERVE = 64
	// previously unimplemented MAP_INHERIT
	MAP_RESERVED0080 = 128
	// for MAP_FILE, don't change file size
	MAP_NOEXTEND = 256
	// region may contain semaphores
	MAP_HASSEMAPHORE = 512
	// don't cache pages for this mapping
	MAP_NOCACHE = 1024
	// Allocate a region that will be used for JIT purposes
	MAP_JIT = 2048
)

// Mapping type
const (
	MAP_FILE = 0
	// allocated from memory, swap space
	MAP_ANON      = 4096
	MAP_ANONYMOUS = 4096
)

// The MAP_RESILIENT_* flags can be used when the caller wants to map some
// possibly unreliable memory and be able to access it safely, possibly
// getting the wrong contents rather than raising any exception.
// For safety reasons, such mappings have to be read-only (PROT_READ access
// only).
//
// MAP_RESILIENT_CODESIGN:
//
//	     accessing this mapping will not generate code-signing violations,
//		even if the contents are tainted.
//
// MAP_RESILIENT_MEDIA:
//
//	accessing this mapping will not generate an exception if the contents
//	are not available (unreachable removable or remote media, access beyond
//	end-of-file, ...).  Missing contents will be replaced with zeroes.
const (
	MAP_RESILIENT_CODESIGN = 8192
	// no backing-store failures
	MAP_RESILIENT_MEDIA = 16384
)

// Return virtual addresses <4G only
const MAP_32BIT = 32768

// Flags used to support translated processes.
const MAP_TRANSLATED_ALLOW_EXECUTE = 131072

// UNIX03 compliance
const MAP_UNIX03 = 262144

// Allocate a region that will be protected by TPRO
const MAP_TPRO = 524288

// Process memory locking
const (
	MCL_CURRENT = 1
	// [ML] Lock all future memory as well
	MCL_FUTURE = 2
)

// msync() flags
const (
	MS_ASYNC = 1
	// [MF|SIO] invalidate all cached data
	MS_INVALIDATE = 2
	// [MF|SIO] msync synchronously
	MS_SYNC = 16
)

const (
	// invalidate pages, leave mapped
	MS_KILLPAGES = 4
	// deactivate pages, leave mapped
	MS_DEACTIVATE = 8
)

// Advice to madvise
const (
	POSIX_MADV_NORMAL = 0
	// [MC1] expect random page refs
	POSIX_MADV_RANDOM = 1
	// [MC1] expect sequential page refs
	POSIX_MADV_SEQUENTIAL = 2
	// [MC1] will need these pages
	POSIX_MADV_WILLNEED = 3
	// [MC1] dont need these pages
	POSIX_MADV_DONTNEED = 4
)

const (
	MADV_NORMAL     = 0
	MADV_RANDOM     = 1
	MADV_SEQUENTIAL = 2
	MADV_WILLNEED   = 3
	MADV_DONTNEED   = 4
	// pages unneeded, discard contents
	MADV_FREE = 5
	// zero the wired pages that have not been unwired before the entry is deleted
	MADV_ZERO_WIRED_PAGES = 6
	// pages can be reused (by anyone)
	MADV_FREE_REUSABLE = 7
	// caller wants to reuse those pages
	MADV_FREE_REUSE = 8
	MADV_CAN_REUSE  = 9
	// page out now (internal only)
	MADV_PAGEOUT = 10
)

// Return bits from mincore
const (
	MINCORE_INCORE = 1
	// Page has been referenced by us
	MINCORE_REFERENCED = 2
	// Page has been modified by us
	MINCORE_MODIFIED = 4
	// Page has been referenced
	MINCORE_REFERENCED_OTHER = 8
	// Page has been modified
	MINCORE_MODIFIED_OTHER = 16
	// Page has been paged out
	MINCORE_PAGED_OUT = 32
	// Page has been copied
	MINCORE_COPIED = 64
	// Page belongs to an anonymous object
	MINCORE_ANONYMOUS = 128
)

